def find_path(graph, start, goal):
    def heuristic(a, b):
        # Simple straight-line distance heuristic (Euclidean distance)
        (x1, y1) = a
        (x2, y2) = b
        return abs(x1 - x2) + abs(y1 - y2)

    def a_star_search(graph, start, goal):
        open_list = set([start])
        closed_list = set()
        g = {start: 0}
        parents = {start: None}
        f = {start: heuristic(start, goal)}

        while open_list:
            current = min(open_list, key=lambda x: f[x])
            if current == goal:
                path = []
                while current:
                    path.append(current)
                    current = parents[current]
                return path[::-1]  # Return path from start to goal

            open_list.remove(current)
            closed_list.add(current)

            for neighbor, edge_cost in graph[current]:
                if neighbor in closed_list:
                    continue
                tentative_g = g[current] + edge_cost
                if neighbor not in open_list or tentative_g < g.get(neighbor, float('inf')):
                    g[neighbor] = tentative_g
                    f[neighbor] = tentative_g + heuristic(neighbor, goal)
                    if neighbor not in open_list:
                        open_list.add(neighbor)
                    parents[neighbor] = current

        return None

    # Run A* search
    path = a_star_search(graph, start, goal)
    return path
